<?php
declare(strict_types=1);
namespace App\Application\Assistant\Service;
use App\Application\Assistant\DTO\Request\CreateAssistantMessageRequestDto;use App\Application\Assistant\DTO\Response\AssistantMessageResponseDto;use App\Application\Assistant\Mapper\AssistantResponseMapper;use App\Application\Assistant\Port\AssistantProviderInterface;use App\Domain\Assistant\Entity\AssistantMessage;use App\Domain\Assistant\Repository\AssistantConversationRepositoryInterface;use App\Domain\Assistant\Repository\SyllabusEvidenceRetrieverInterface;
final class SendAssistantMessageService { public function __construct(private readonly AssistantConversationRepositoryInterface $conversations,private readonly SyllabusEvidenceRetrieverInterface $evidence,private readonly AssistantProviderInterface $provider,private readonly AssistantResponseMapper $mapper){} public function sendForUser(string $userId,CreateAssistantMessageRequestDto $input):AssistantMessageResponseDto { $conversation=$this->conversations->findConversationForUser($input->conversationId,$userId);if($conversation===null)throw new \DomainException('Conversa nao encontrada.');$now=new \DateTimeImmutable('now');$this->conversations->saveMessage(new AssistantMessage(self::id(),$conversation->id,'USER',trim($input->content),null,null,[],$now));$evidence=$this->evidence->retrieve($conversation->syllabusId,$input->content);if($evidence===[])throw new \DomainException('Nao foram encontradas evidencias no edital para esta pergunta.');$answer=$this->provider->answer($input->content,$evidence);$message=new AssistantMessage(self::id(),$conversation->id,'ASSISTANT',$answer->content,$answer->provider,$answer->model,$answer->evidence,new \DateTimeImmutable('now'));$this->conversations->saveMessage($message);return $this->mapper->message($message); } private static function id():string{return bin2hex(random_bytes(16));} }
